use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let s: String = match input {
        Value::String(s) => s,
        _ => return Value::Null,
    };

    let mut chars = s.chars().peekable();
    let mut sign = 1;
    let mut digits = Vec::new();
    let mut decimal_found = false;

    while let Some(c) = chars.next() {
        if c == '-' {
            if sign == 1 {
                sign = -1;
            }
        } else if c == '+' {
            // Ignore leading plus
        } else if c == '.' {
            if decimal_found {
                return Value::Null;
            }
            decimal_found = true;
        } else if c.is_ascii_digit() {
            digits.push(c);
        } else {
            break;
        }
    }

    if digits.is_empty() {
        return Value::Null;
    }

    let mut integer_part: i64 = 0;
    let mut fractional_part: i64 = 0;

    for c in digits.iter() {
        integer_part = integer_part * 10 + (c.to_digit(10).unwrap() as i64);
    }

    if decimal_found {
        let mut frac_digits = Vec::new();
        while let Some(c) = chars.next() {
            if c == '.' {
                continue;
            } else if c.is_ascii_digit() {
                frac_digits.push(c);
            } else {
                break;
            }
        }

        if frac_digits.len() != 2 {
            return Value::Null;
        }

        fractional_part = frac_digits
            .iter()
            .map(|c| c.to_digit(10).unwrap() as i64)
            .fold(0, |acc, d| acc * 10 + d);
    }

    let total_cents = sign * (integer_part * 100 + fractional_part);

    // Check magnitude limit: <= 1000000 pounds = 100000000 cents
    if total_cents.abs() > 100_000_000 {
        return Value::Null;
    }

    Value::Number(serde_json::Number::from(total_cents))
}
